/**
 * Generates the app icon, adaptive icon, splash mark and web favicon.
 *
 * The assets are committed, so this only needs running when the mark or the
 * brand colour changes. It exists rather than a set of opaque binaries because
 * a paw drawn from arithmetic can be adjusted and regenerated by anyone; a PNG
 * that arrived from somewhere else cannot.
 *
 * Run with:  node scripts/make-brand-assets.mjs
 */

import { deflateSync } from "node:zlib";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const OUT = join(dirname(fileURLToPath(import.meta.url)), "..", "assets");

/** VetKeep's deep green, the same value as palette.brand in src/ui/tokens.ts. */
const BRAND = [0x17, 0x4d, 0x35];
const WHITE = [0xff, 0xff, 0xff];

// --- PNG encoding -----------------------------------------------------------

const CRC_TABLE = (() => {
  const table = new Int32Array(256);
  for (let n = 0; n < 256; n += 1) {
    let c = n;
    for (let k = 0; k < 8; k += 1) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c;
  }
  return table;
})();

function crc32(buffer) {
  let c = 0xffffffff;
  for (let i = 0; i < buffer.length; i += 1) c = CRC_TABLE[(c ^ buffer[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function chunk(type, data) {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length);
  const typeBuffer = Buffer.from(type, "ascii");
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(Buffer.concat([typeBuffer, data])));
  return Buffer.concat([length, typeBuffer, data, crc]);
}

function encodePng(width, height, rgba) {
  const signature = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 6; // truecolour with alpha
  const stride = width * 4;
  // One filter byte per scanline. Filter 0 (none) keeps this readable; the
  // images are flat colour, so deflate handles the redundancy anyway.
  const raw = Buffer.alloc((stride + 1) * height);
  for (let y = 0; y < height; y += 1) {
    raw[y * (stride + 1)] = 0;
    rgba.copy(raw, y * (stride + 1) + 1, y * stride, (y + 1) * stride);
  }
  return Buffer.concat([
    signature,
    chunk("IHDR", ihdr),
    chunk("IDAT", deflateSync(raw, { level: 9 })),
    chunk("IEND", Buffer.alloc(0))
  ]);
}

// --- The mark ---------------------------------------------------------------

/** An ellipse in unit space, so the mark scales to any canvas. */
function ellipse(px, py, cx, cy, rx, ry) {
  const dx = (px - cx) / rx;
  const dy = (py - cy) / ry;
  return dx * dx + dy * dy <= 1;
}

/**
 * A paw: four toes over a pad. Chosen because it stays legible at 48px, where
 * a wordmark or a caduceus turns to mush.
 */
function inPaw(x, y) {
  // Every shape is spaced to leave a visible gap from its neighbours. Toes that
  // touch the pad fuse into one blob once the launcher scales this to 48px,
  // which is the size that decides whether the mark is recognisable at all.
  if (ellipse(x, y, 0.5, 0.675, 0.225, 0.155)) return true;
  return (
    ellipse(x, y, 0.225, 0.4, 0.08, 0.1) ||
    ellipse(x, y, 0.4, 0.295, 0.088, 0.118) ||
    ellipse(x, y, 0.6, 0.295, 0.088, 0.118) ||
    ellipse(x, y, 0.775, 0.4, 0.08, 0.1)
  );
}

/**
 * Renders the paw, supersampled 4x4 per pixel. Without it the toes show a hard
 * staircase at every size the launcher actually uses.
 */
function render({ size, background, mark, scale = 1 }) {
  const rgba = Buffer.alloc(size * size * 4);
  const samples = 4;
  const offset = (1 - scale) / 2;

  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      let hits = 0;
      for (let sy = 0; sy < samples; sy += 1) {
        for (let sx = 0; sx < samples; sx += 1) {
          const ux = (x + (sx + 0.5) / samples) / size;
          const uy = (y + (sy + 0.5) / samples) / size;
          // Map into the inset box so the mark can be shrunk inside the
          // canvas, which Android's adaptive icon safe zone requires.
          const mx = (ux - offset) / scale;
          const my = (uy - offset) / scale;
          if (mx >= 0 && mx <= 1 && my >= 0 && my <= 1 && inPaw(mx, my)) hits += 1;
        }
      }

      const coverage = hits / (samples * samples);
      const index = (y * size + x) * 4;

      if (background) {
        for (let c = 0; c < 3; c += 1) {
          rgba[index + c] = Math.round(background[c] * (1 - coverage) + mark[c] * coverage);
        }
        rgba[index + 3] = 255;
      } else {
        for (let c = 0; c < 3; c += 1) rgba[index + c] = mark[c];
        rgba[index + 3] = Math.round(coverage * 255);
      }
    }
  }

  return encodePng(size, size, rgba);
}

// --- Output -----------------------------------------------------------------

mkdirSync(OUT, { recursive: true });

const assets = [
  // iOS refuses transparency in an app icon and applies its own mask, so this
  // one is a full opaque square.
  ["icon.png", render({ size: 1024, background: BRAND, mark: WHITE })],
  // Android composites this over adaptiveIcon.backgroundColor and crops it to
  // whatever shape the launcher uses, so the mark sits inside the safe zone.
  ["adaptive-icon.png", render({ size: 1024, background: null, mark: WHITE, scale: 0.6 })],
  ["splash-icon.png", render({ size: 512, background: null, mark: WHITE, scale: 0.72 })],
  ["favicon.png", render({ size: 48, background: BRAND, mark: WHITE })]
];

for (const [name, buffer] of assets) {
  writeFileSync(join(OUT, name), buffer);
  console.log(`${name}  ${buffer.length} bytes`);
}
